package apicontract

// PromotionTools declares the promotion service operations.
type PromotionTools struct {
	Promote            Binding[PromoteArgs, PromoteResult]             `tool:"promote" summary:"Promote a tested commit to the default branch." desc:"Promote an exact tested source against the authorized target branch. Keep the returned ID and use promote_status to observe completion." mutation:"true" post:"/api/promotions" check:"promote_status"`
	PromoteRetry       Binding[PromoteRetryArgs, PromoteResult]        `tool:"promote_retry" summary:"Retry a durable promotion whose previous attempt failed." desc:"Retry a durable promotion whose previous attempt failed. Use promote_status to observe the same promotion identity." mutation:"true" check:"promote_status"`
	PromoteStatus      Binding[PromoteStatusArgs, PromotionWaitResult] `tool:"promote_status" summary:"Read a promotion and its current outcome." desc:"Observe a durable promotion until it finishes or the wait times out. A promotion retested on a moved default branch continues as its retest; a passed one finishes once its publication is no longer pending." wait:"true"`
	PromotionList      Binding[PromotionListArgs, PromotionPage]       `tool:"promotion_list" command:"promote list" summary:"List durable promotions visible to this caller." desc:"List durable promotions visible to this caller. Use promote_status for the selected promotion and publication_list for delivery."`
	PublicationAbandon Binding[PublicationAbandonArgs, Receipt]        `tool:"publication_abandon" summary:"Abandon a failed publication after investigation." desc:"Abandon an authorized pending or failed publication with an audit reason. Inspect publication_list before attempting a new publication." access:"unscoped_admin" mutation:"true" admin:"publication-abandon" bytes:"131072" check:"publication_list"`
	PublishRetry       Binding[PublishRetryArgs, Receipt]              `tool:"publish_retry" command:"publication retry" summary:"Retry a failed upstream publication." desc:"Retry an authorized failed publication without rerunning passed steps. Use publication_list to inspect its durable outcome." mutation:"true" check:"publication_list"`
	ReceiveOutbox      Binding[ReceiveOutboxArgs, OutboxResult]        `tool:"receive_outbox" summary:"Read or repair pending push delivery obligations." mutation:"true" desc:"Inspect or repair durable receive obligations after delivery recovery fails. Read the returned obligation state before repeating a repair." access:"repository_admin" check:"receive_outbox"`
	Sync               Binding[SyncArgs, Receipt]                      `tool:"sync" summary:"Publish a parked branch upstream without running it." desc:"Publish the exact head of a parked non-default branch upstream without running it. Inspect the receipt to confirm publication." mutation:"true" check:"run_list"`
	PublicationList    Binding[PublicationListArgs, PublicationPage]   `tool:"publication_list" summary:"List publication receipts visible to this caller." desc:"List authorized publication receipts, including failed deletions. Use publish_retry or publication_abandon on the exact returned ID."`
}
